/** bool8 PartyHasMonWithSurf(void) */
export function PartyHasMonWithSurf(): any {
  let i: any = null;

      if (!TestPlayerAvatarFlags(PLAYER_AVATAR_FLAG_SURFING))
      {
          for (i = 0; i < PARTY_SIZE; i++)
          {
              if (GetMonData(gPlayerParty[i], MON_DATA_SPECIES) == SPECIES_NONE)
                  break;
              if (MonKnowsMove(gPlayerParty[i], MOVE_SURF))
                  return TRUE;
          }
      }
      return FALSE;
}

/** bool8 IsPlayerSurfingNorth(void) */
export function IsPlayerSurfingNorth(): any {
  if (GetPlayerMovementDirection() == DIR_NORTH && TestPlayerAvatarFlags(PLAYER_AVATAR_FLAG_SURFING))
          return TRUE;
      else
          return FALSE;
}

/** bool8 IsPlayerFacingSurfableFishableWater(void) */
export function IsPlayerFacingSurfableFishableWater(): any {
  let playerObjEvent: any =gObjectEvents[gPlayerAvatar.objectEventId];
      let x: any = playerObjEvent.currentCoords.x;
      let y: any = playerObjEvent.currentCoords.y;

      MoveCoords(playerObjEvent.facingDirection,x,y);
      if (GetCollisionAtCoords(playerObjEvent, x, y, playerObjEvent.facingDirection) == COLLISION_ELEVATION_MISMATCH
       && PlayerGetElevation() == ELEVATION_DEFAULT
       && MetatileBehavior_IsSurfableFishableWater(MapGridGetMetatileBehaviorAt(x, y)))
          return TRUE;
      else
          return FALSE;
}

