/** static u8 GetPlayerAvatarStateTransitionByGraphicsId(u8 graphicsId, u8 gender) */
export function GetPlayerAvatarStateTransitionByGraphicsId(graphicsId: any, gender: any): any {
  let i: any = null;

      for (i = 0; i < ARRAY_COUNT(sPlayerAvatarGfxToStateFlag[0]); i++)
      {
          if (sPlayerAvatarGfxToStateFlag[gender][i].graphicsId == graphicsId)
              return sPlayerAvatarGfxToStateFlag[gender][i].playerFlag;
      }
      return PLAYER_AVATAR_FLAG_ON_FOOT;
}

/** u8 GetPlayerAvatarGraphicsIdByCurrentState(void) */
export function GetPlayerAvatarGraphicsIdByCurrentState(): any {
  let i: any = null;
      let flags: any = gPlayerAvatar.flags;

      for (i = 0; i < ARRAY_COUNT(sPlayerAvatarGfxToStateFlag[0]); i++)
      {
          if (sPlayerAvatarGfxToStateFlag[gPlayerAvatar.gender][i].playerFlag & flags)
              return sPlayerAvatarGfxToStateFlag[gPlayerAvatar.gender][i].graphicsId;
      }
      return 0;
}

/** void SetPlayerAvatarExtraStateTransition(u8 graphicsId, u8 transitionFlag) */
export function SetPlayerAvatarExtraStateTransition(graphicsId: any, transitionFlag: any): any {
  let stateFlag: any = GetPlayerAvatarStateTransitionByGraphicsId(graphicsId, gPlayerAvatar.gender);

      gPlayerAvatar.transitionFlags |= stateFlag | transitionFlag;
      DoPlayerAvatarTransition();
}

/** void InitPlayerAvatar(s16 x, s16 y, u8 direction, u8 gender) */
export function InitPlayerAvatar(x: any, y: any, direction: any, gender: any): any {
  let playerObjEventTemplate: any = null;
      let objectEventId: any = null;
      let objectEvent: any = null;

      playerObjEventTemplate.localId = LOCALID_PLAYER;
      playerObjEventTemplate.graphicsId = GetPlayerAvatarGraphicsIdByStateIdAndGender(PLAYER_AVATAR_STATE_NORMAL, gender);
      playerObjEventTemplate.x = x - MAP_OFFSET;
      playerObjEventTemplate.y = y - MAP_OFFSET;
      playerObjEventTemplate.elevation = ELEVATION_TRANSITION;
      playerObjEventTemplate.movementType = MOVEMENT_TYPE_PLAYER;
      playerObjEventTemplate.movementRangeX = 0;
      playerObjEventTemplate.movementRangeY = 0;
      playerObjEventTemplate.trainerType = TRAINER_TYPE_NONE;
      playerObjEventTemplate.trainerRange_berryTreeId = 0;
      playerObjEventTemplate.script = NULL;
      playerObjEventTemplate.flagId = 0;
      objectEventId = SpawnSpecialObjectEvent(playerObjEventTemplate);
      objectEvent =gObjectEvents[objectEventId];
      objectEvent.isPlayer = TRUE;
      objectEvent.warpArrowSpriteId = CreateWarpArrowSprite();
      ObjectEventTurn(objectEvent, direction);
      ClearPlayerAvatarInfo();
      gPlayerAvatar.runningState = NOT_MOVING;
      gPlayerAvatar.tileTransitionState = T_NOT_MOVING;
      gPlayerAvatar.objectEventId = objectEventId;
      gPlayerAvatar.spriteId = objectEvent.spriteId;
      gPlayerAvatar.gender = gender;
      SetPlayerAvatarStateMask(PLAYER_AVATAR_FLAG_CONTROLLABLE | PLAYER_AVATAR_FLAG_ON_FOOT);
}

