/** static void AlignFishingAnimationFrames(void) */
export function AlignFishingAnimationFrames(): any {
  let playerSprite: any =gSprites[gPlayerAvatar.spriteId];
      let animCmdIndex: any = null;
      let animType: any = null;

      AnimateSprite(playerSprite);
      playerSprite.x2 = 0;
      playerSprite.y2 = 0;
      animCmdIndex = playerSprite.animCmdIndex;
      if (playerSprite.anims[playerSprite.animNum][animCmdIndex].type == -1)
      {
          animCmdIndex--;
      }
      else
      {
          playerSprite.animDelayCounter++;
          if (playerSprite.anims[playerSprite.animNum][animCmdIndex].type == -1)
              animCmdIndex--;
      }
      animType = playerSprite.anims[playerSprite.animNum][animCmdIndex].type;
      if (animType == 1 || animType == 2 || animType == 3)
      {
          playerSprite.x2 = 8;
          if (GetPlayerFacingDirection() == 3)
              playerSprite.x2 = -8;
      }
      if (animType == 5)
          playerSprite.y2 = -8;
      if (animType == 10 || animType == 11)
          playerSprite.y2 = 8;
      if (gPlayerAvatar.flags & PLAYER_AVATAR_FLAG_SURFING)
          SetSurfBlob_PlayerOffset(gObjectEvents[gPlayerAvatar.objectEventId].fieldEffectSpriteId, TRUE, playerSprite.y2);
}

/** void SetSpinStartFacingDir(u8 direction) */
export function SetSpinStartFacingDir(direction: any): any {
  sSpinStartFacingDir = direction;
}

/** static u8 GetSpinStartFacingDir(void) */
export function GetSpinStartFacingDir(): any {
  if (sSpinStartFacingDir == DIR_NONE)
          return DIR_SOUTH;

      return sSpinStartFacingDir;
}

/** static void Task_DoPlayerSpinExit(u8 taskId) */
export function Task_DoPlayerSpinExit(taskId: any): any {
  let object: any =gObjectEvents[gPlayerAvatar.objectEventId];
      let sprite: any =gSprites[object.spriteId];
      let data: any = gTasks[taskId].data;

      switch (tState)
      {
          case 0:  
              if (!ObjectEventClearHeldMovementIfFinished(object))
                  return;

              SetSpinStartFacingDir(object.facingDirection);
              tSpinDelayTimer = 0;
              tSpeed = 1;
              tCurY = (sprite.y + sprite.y2) << 4;
              sprite.y2 = 0;
              CameraObjectFreeze();
              object.fixedPriority = TRUE;
              sprite.oam.priority = 0;
              sprite.subpriority = 0;
              sprite.subspriteMode = SUBSPRITES_OFF;
              tState++;
          case 1:  
              TrySpinPlayerForWarp(object,tSpinDelayTimer);

               
              tCurY -= tSpeed;
              tSpeed += 3;
              sprite.y = tCurY >> 4;

               
              if (sprite.y + gTotalCameraPixelOffsetY < -32)
                  tState++;
              break;
          case 2:
              DestroyTask(taskId);
              break;
      }
}

