/** static void Task_DoPlayerSpinEntrance(u8 taskId) */
export function Task_DoPlayerSpinEntrance(taskId: any): any {
  let object: any =gObjectEvents[gPlayerAvatar.objectEventId];
      let sprite: any =gSprites[object.spriteId];
      let data: any = gTasks[taskId].data;

      switch (tState)
      {
          case 0:
               
               
               
              tStartDir = GetSpinStartFacingDir();
              ObjectEventForceSetHeldMovement(object, GetFaceDirectionMovementAction(sSpinDirections[tStartDir]));
              tSpinDelayTimer = 0;
              tSpeed = 116;
              tDestY = sprite.y;
              tPriority = sprite.oam.priority;
              tSubpriority = sprite.subpriority;
              tCurY = -(sprite.y2 + 32) * 16;
              sprite.y2 = 0;
              CameraObjectFreeze();
              object.fixedPriority = TRUE;
              sprite.oam.priority = 1;
              sprite.subpriority = 0;
              sprite.subspriteMode = SUBSPRITES_OFF;
              tState++;
          case 1:  
              TrySpinPlayerForWarp(object,tSpinDelayTimer);

               
              tCurY += tSpeed;
              tSpeed -= 3;
              if (tSpeed < 4)
                  tSpeed = 4;
              sprite.y = tCurY >> 4;

               
              if (sprite.y >= tDestY)
              {
                  sprite.y = tDestY;
                  tGroundTimer = 0;
                  tState++;
              }
              break;
          case 2:  
              TrySpinPlayerForWarp(object,tSpinDelayTimer);
              if (++tGroundTimer > 8)
                  tState++;
              break;
          case 3:  
              if (tStartDir == TrySpinPlayerForWarp(object,tSpinDelayTimer))
              {
                  object.fixedPriority = 0;
                  sprite.oam.priority = tPriority;
                  sprite.subpriority = tSubpriority;
                  CameraObjectReset();
                  DestroyTask(taskId);
              }
              break;
      }
}

/** static u8 TrySpinPlayerForWarp(struct ObjectEvent *object, s16 *delayTimer) */
export function TrySpinPlayerForWarp(object: any, delayTimer: any): any {
  if (delayTimer < 8 && ++(delayTimer) < 8)
          return object.facingDirection;

      if (!ObjectEventCheckHeldMovementStatus(object))
          return object.facingDirection;

      ObjectEventForceSetHeldMovement(object, GetFaceDirectionMovementAction(sSpinDirections[object.facingDirection]));
      delayTimer = 0;
      return sSpinDirections[object.facingDirection];
}

